int32_t samples[{{sample_count}}]; size_t br;
i2s_read(I2S_NUM_0, samples, sizeof(samples), &br, portMAX_DELAY);
double sum = 0;
int n = br / sizeof(int32_t);
for (int i = 0; i < n; i++) {
    double s = samples[i] >> 14;
    sum += s * s;
}
double rms = sqrt(sum / n);
double db = 20 * log10(rms + 1);
ESP_LOGI("AUDIO", "rms=%.0f dB=%.1f", rms, db);
